// 1. 装饰器模式基础结构
public interface Component {
    void operation();
}
public class ConcreteComponent implements Component {
    @Override
    public void operation() {
        System.out.println("基础操作");
    }
}
public abstract class Decorator implements Component {
    protected Component component;

    public Decorator(Component component) {
        this.component = component;
    }

    @Override
    public void operation() {
        component.operation();
    }
}
public class ConcreteDecoratorA extends Decorator {
    public ConcreteDecoratorA(Component component) {
        super(component);
    }

    @Override
    public void operation() {
        super.operation();
        System.out.println("装饰器A的额外功能");
    }
}

// 2. Java IO装饰器示例
// InputStream是组件接口
// FileInputStream是具体组件
// FilterInputStream是装饰器基类
// BufferedInputStream是具体装饰器
InputStream is = new BufferedInputStream(new FileInputStream("file.txt"));

// 3. 自定义装饰器：添加日志功能
public class LoggingInputStream extends FilterInputStream {
    public LoggingInputStream(InputStream in) {
        super(in);
    }

    @Override
    public int read() throws IOException {
        int b = super.read();
        System.out.println("读取字节: " + b);
        return b;
    }
}

